import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    idx = 1

    dice = []
    sizes = []

    for _ in range(n):
        k = data[idx]
        idx += 1
        sizes.append(k)

        freq = {}
        for _ in range(k):
            a = data[idx]
            idx += 1
            freq[a] = freq.get(a, 0) + 1
        dice.append(freq)

    ans = 0.0

    for i in range(n):
        for j in range(i + 1, n):
            d1, d2 = dice[i], dice[j]
            if len(d1) > len(d2):
                d1, d2 = d2, d1

            same = 0
            for value, count in d1.items():
                same += count * d2.get(value, 0)

            ans = max(ans, same / (sizes[i] * sizes[j]))

    print(f"{ans:.15f}")

if __name__ == "__main__":
    solve()
